service = env['onedrive.service']
# Llamar al método de diagnóstico que ya se encarga de enviar notificaciones
result = service.diagnose_connection()

# Definir una acción de notificación con mensaje y tipo según el resultado
if result['success']:
    message = 'Conexión establecida correctamente'
    notification_type = 'success'
else:
    message = 'Error de conexión: ' + result.get('error', 'Falló el diagnóstico')
    notification_type = 'danger'

action = {
    'type': 'ir.actions.client',
    'tag': 'display_notification',
    'params': {
        'title': 'Diagnóstico OneDrive',
        'message': message,
        'sticky': False,
        'type': notification_type,
    }
}

service = env['onedrive.service'] result = service.sync_onedrive_files()
# En lugar de mostrar una notificación, abrimos una ventana modal con el resumen if result['success']: # Crear el wizard con el resumen de sincronización wizard_vals = { 'name': 'Resumen de Sincronización OneDrive', 'success': True, 'synced_count': result.get('synced_count', 0), 'created_count': result.get('created_count', 0), 'updated_count': result.get('updated_count', 0), } else: # Crear el wizard con información de error wizard_vals = { 'name': 'Error de Sincronización OneDrive', 'success': False, 'error_message': result.get('error', 'Error desconocido'), }
# Crear el wizard y devolver la acción para abrirlo summary_id = env['onedrive.sync.summary'].create(wizard_vals)
action = { 'type': 'ir.actions.act_window', 'name': 'Resumen de Sincronización', 'res_model': 'onedrive.sync.summary', 'res_id': summary_id.id, 'view_mode': 'form', 'target': 'new', 'flags': {'mode': 'readonly'}, }
